// updateAudioVolume implements the v1.0.0 stage-video audio seam.
// HTML media volume remains linear, as in the browser port.
func (bgv *bgVideo) updateAudioVolume() {
	if !bgv.opened { return }
	_, noMusic := sys.cmdFlags["-nomusic"]
	_, noSound := sys.cmdFlags["-nosound"]
	volume := float64(Clamp(int32(bgv.volume), 0, int32(sys.cfg.Sound.MaxBGMVolume))) / 100
	volume *= float64(sys.cfg.Sound.BGMVolume) / 100
	volume *= float64(sys.cfg.Sound.MasterVolume) / 100
	if volume > 1 { volume = 1 }
	if volume < 0 { volume = 0 }
	bgv.el.Set("volume", volume)
	bgv.updateMuted()
	if noMusic || noSound { bgv.el.Set("muted", true) }
}

